const BUILTIN_GLB_ASSETS=[{"id":"lighthouse","label":"Маяк","variants":{"low":"","high":""},"license":"TrussLab original, CC0 demo geometry, not a surveyed landmark"},{"id":"warehouse","label":"Склад","variants":{"low":"","high":""},"license":"TrussLab original, CC0 demo geometry, not a surveyed landmark"},{"id":"crane","label":"Портовый кран","variants":{"low":"","high":""},"license":"TrussLab original, CC0 demo geometry, not a surveyed landmark"}];






