  let fogFactor = clamp((dist-scene.fog.x*.42)/(scene.fog.x*.85),0.0,1.0);
  let sky = select(select(vec3<f32>(0.54,0.72,0.82),vec3<f32>(0.70,0.51,0.39),sunset),vec3<f32>(0.045,0.065,0.105),night);
